require_once __DIR__ . '/_layout.php';requirePermission('customers.manage');$ids=currentAgencyIds();if(!$ids)$ids=[0];$ph=implode(',',array_fill(0,count($ids),'?'));$customers=dbFetchAll("SELECT id,first_name,last_name,agency_id FROM customers WHERE agency_id IN ($ph) AND archived_at IS NULL ORDER BY last_name,first_name",$ids);$customerId=(int)($_GET['id']??$_POST['customer_id']??($customers[0]['id']??0));$customer=dbFetchOne('SELECT * FROM customers WHERE id=:id',['id'=>$customerId]);if($customer)requireAgencyAccess($customer['agency_id']);
if(requestMethod()==='POST'){requireCsrfPost();$action=$_POST['action']??'';try{if(!$customer)throw new InvalidArgumentException('Customer not found.');if($action==='driver'){$birth=validDateValue($_POST['date_of_birth']??'');$issue=validDateValue($_POST['licence_issue_date']??'');$expiry=validDateValue($_POST['licence_expires_at']??'');if(!$birth||!$expiry||$expiry<=new DateTimeImmutable('today'))throw new InvalidArgumentException('Valid birth and future licence expiry dates are required.');if($birth->diff(new DateTimeImmutable('today'))->y<appConfig('minimum_driver_age'))throw new DomainException('Driver is below the configured minimum age.');if($issue&&$issue->diff(new DateTimeImmutable('today'))->m+($issue->diff(new DateTimeImmutable('today'))->y*12)<appConfig('minimum_licence_months'))throw new DomainException('Driver does not meet minimum licence seniority.');dbExecute("INSERT INTO additional_drivers(customer_id,first_name,last_name,identity_number,date_of_birth,licence_number,licence_issue_date,licence_expires_at,licence_country,phone,status,created_by)VALUES(:customer,:first,:last,:identity,:birth,:licence,:issue,:expiry,:country,:phone,'active',:user)",['customer'=>$customerId,'first'=>trim((string)$_POST['first_name']),'last'=>trim((string)$_POST['last_name']),'identity'=>trim((string)($_POST['identity_number']??'')),'birth'=>$birth->format('Y-m-d'),'licence'=>trim((string)$_POST['licence_number']),'issue'=>$issue?$issue->format('Y-m-d'):null,'expiry'=>$expiry->format('Y-m-d'),'country'=>strtoupper(substr(trim((string)($_POST['licence_country']??'MA')),0,2)),'phone'=>trim((string)($_POST['phone']??'')),'user'=>currentUserId()]);auditLog('additional_driver.created','additional_driver',db()->lastInsertId(),null,['customer_id'=>$customerId],$customer['agency_id']);flash('success','Additional driver added.');}elseif($action==='document'){$stored=storeValidatedDocument($_FILES['document'],'customer_documents');dbExecute('INSERT INTO customer_documents(customer_id,document_type,document_number,issuing_country,issued_at,expires_at,storage_path,original_name,mime_type,file_size,created_by)VALUES(:customer,:type,:number,:country,:issued,:expires,:path,:original,:mime,:size,:user)',['customer'=>$customerId,'type'=>validateChoice($_POST['document_type']??'',['identity','passport','driving_licence','company','other'],'other'),'number'=>trim((string)($_POST['document_number']??'')),'country'=>strtoupper(substr(trim((string)($_POST['issuing_country']??'MA')),0,2)),'issued'=>($_POST['issued_at']??'')?:null,'expires'=>($_POST['expires_at']??'')?:null,'path'=>$stored['path'],'original'=>$stored['original_name'],'mime'=>$stored['mime_type'],'size'=>$stored['size'],'user'=>currentUserId()]);auditLog('customer.document_created','customer_document',db()->lastInsertId(),null,['customer_id'=>$customerId],$customer['agency_id']);flash('success','Customer document stored.');} }catch(InvalidArgumentException|DomainException $exception){flash('danger',$exception->getMessage());}catch(Throwable $exception){reportDatabaseError($exception,'Customer file operation failed');flash('danger','The customer file operation could not be completed.');}safeRedirect('customer_detail.php?id='.$customerId);}
$drivers=$customer?dbFetchAll('SELECT * FROM additional_drivers WHERE customer_id=:id AND archived_at IS NULL ORDER BY created_at DESC',['id'=>$customerId]):[];$documents=$customer?dbFetchAll('SELECT * FROM customer_documents WHERE customer_id=:id AND archived_at IS NULL ORDER BY expires_at',['id'=>$customerId]):[];$history=$customer?dbFetchAll('SELECT r.reference,r.pickup_at,r.return_at,r.status,r.total_amount,r.currency,v.registration_number FROM reservations r LEFT JOIN vehicles v ON v.id=r.vehicle_id WHERE r.customer_id=:id ORDER BY r.created_at DESC',['id'=>$customerId]):[];$payments=$customer?dbFetchAll('SELECT p.payment_number,p.amount,p.currency,p.paid_at,p.status FROM payments p JOIN reservations r ON r.id=p.reservation_id WHERE r.customer_id=:id ORDER BY p.paid_at DESC',['id'=>$customerId]):[];
backofficeHeader('Customer files','customer_detail.php');?><?php pageHeader('Customer files', 'Review customer documents, additional drivers, rentals, and payments.', ['breadcrumbs'=>[['label'=>'Customers','href'=>'customers.php'],['label'=>'Customer files']],'primary'=>['label'=>'Add driver','href'=>'#new-driver']]); ?><form class="filters" method="get"><label>Customer<select name="id" onchange="this.form.submit()"><?php foreach($customers as $c):?><option value="<?=e($c['id'])?>" <?=$customerId===(int)$c['id']?'selected':''?>><?=e($c['last_name'].' '.$c['first_name'])?></option><?php endforeach;?></select></label></form><?php if($customer):?><div class="grid"><section class="card" id="new-driver"><h2>Add additional driver</h2><form method="post"><?=csrfField()?><input type="hidden" name="action" value="driver"><input type="hidden" name="customer_id" value="<?=e($customerId)?>"><label>First name<input name="first_name" required></label><label>Last name<input name="last_name" required></label><label>Identity<input name="identity_number"></label><label>Date of birth<input type="date" name="date_of_birth" required></label><label>Licence number<input name="licence_number" required></label><label>Licence issue<input type="date" name="licence_issue_date"></label><label>Licence expiry<input type="date" name="licence_expires_at" required></label><label>Licence country<input name="licence_country" value="MA"></label><label>Phone<input name="phone"></label><button class="btn primary">Add driver</button></form><h2>Drivers</h2><div class="table-wrap"><table><tr><th>Name</th><th>Licence</th><th>Expires</th><th>Status</th></tr><?php foreach($drivers as $d):?><tr><td><?=e($d['first_name'].' '.$d['last_name'])?></td><td><?=e($d['licence_number'])?></td><td><?=e($d['licence_expires_at'])?></td><td><?=statusBadge($d['status'])?></td></tr><?php endforeach;?></table></div></section><section class="card"><h2>Upload document</h2><form method="post" enctype="multipart/form-data"><?=csrfField()?><input type="hidden" name="action" value="document"><input type="hidden" name="customer_id" value="<?=e($customerId)?>"><label>Type<select name="document_type"><option>identity</option><option>passport</option><option>driving_licence</option><option>company</option><option>other</option></select></label><label>Number<input name="document_number"></label><label>Country<input name="issuing_country" value="MA"></label><label>Issued<input type="date" name="issued_at"></label><label>Expires<input type="date" name="expires_at"></label><label>PDF or image<input type="file" name="document" required accept="application/pdf,image/jpeg,image/png,image/webp"></label><button class="btn primary">Store document</button></form><h2>Documents</h2><div class="table-wrap"><table><tr><th>Type</th><th>Number</th><th>Expires</th></tr><?php foreach($documents as $d):?><tr><td><?=e($d['document_type'])?></td><td><?=e($d['document_number'])?></td><td><?=e($d['expires_at'])?></td></tr><?php endforeach;?></table></div></section></div><div class="grid" style="margin-top:1rem"><section class="card"><h2>Rental history</h2><div class="table-wrap"><table><tr><th>Reference</th><th>Vehicle</th><th>Period</th><th>Status</th><th>Total</th></tr><?php foreach($history as $h):?><tr><td><?=e($h['reference'])?></td><td><?=e($h['registration_number'])?></td><td><?=e($h['pickup_at'])?><br><?=e($h['return_at'])?></td><td><?=statusBadge($h['status'])?></td><td><?=money($h['total_amount'],$h['currency'])?></td></tr><?php endforeach;?></table></div></section><section class="card"><h2>Payment history</h2><div class="table-wrap"><table><tr><th>Number</th><th>Date</th><th>Amount</th><th>Status</th></tr><?php foreach($payments as $p):?><tr><td><?=e($p['payment_number'])?></td><td><?=e($p['paid_at'])?></td><td><?=money($p['amount'],$p['currency'])?></td><td><?=statusBadge($p['status'])?></td></tr><?php endforeach;?></table></div></section></div><?php endif;?><?php backofficeFooter();

